export const MATERIAL_CLOSURE_RELEASE = Object.freeze({"version":"identity-v1","checksum":"440407bc2d22618997345e90c2a8cb097e813b7b5277c95694d31fdef878aaf8","manifestSha256":"cf1798797883e2a70547ac2f79cdf38a1b36fe06c7736fb2f42dffd28bafe7e0","sql":"-- Core schema version identity-v1 (closed build artifact).\n\nSET ROLE backbone_owner;\n\n-- gov/identity_accounts.sql\n\n-- Tenant identity state is crossing-only, including for the service role.\nCREATE TABLE app.identity_accounts (\n  workspace_id uuid NOT NULL REFERENCES app.workspaces(id),\n  principal_id uuid NOT NULL, issuer text NOT NULL CHECK(length(issuer) BETWEEN 1 AND 2048), subject text NOT NULL CHECK(length(subject) BETWEEN 1 AND 512), PRIMARY KEY(workspace_id,issuer,subject), UNIQUE(workspace_id,principal_id), FOREIGN KEY(workspace_id,principal_id) REFERENCES app.principals(workspace_id,id)\n);\nALTER TABLE app.identity_accounts ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_accounts FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_accounts AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_accounts FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_accounts FROM PUBLIC, backbone_app, backbone_operator;\n\nGRANT SELECT,INSERT,UPDATE,DELETE ON app.identity_accounts TO backbone_gov;\n\n-- gov/identity_sessions.sql\n\n-- Tenant identity state is crossing-only, including for the service role.\nCREATE TABLE app.identity_sessions (\n  workspace_id uuid NOT NULL REFERENCES app.workspaces(id),\n  token_hash text NOT NULL CHECK(token_hash ~ '^[a-f0-9]{64}$'), principal_id uuid NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, PRIMARY KEY(workspace_id,token_hash), FOREIGN KEY(workspace_id,principal_id) REFERENCES app.principals(workspace_id,id)\n);\nALTER TABLE app.identity_sessions ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_sessions FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_sessions AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_sessions FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_sessions FROM PUBLIC, backbone_app, backbone_operator;\n\nGRANT SELECT,INSERT,UPDATE,DELETE ON app.identity_sessions TO backbone_gov;\n\n-- gov/identity_invitations.sql\n\n-- Tenant identity state is crossing-only, including for the service role.\nCREATE TABLE app.identity_invitations (\n  workspace_id uuid NOT NULL REFERENCES app.workspaces(id),\n  token_hash text NOT NULL CHECK(token_hash ~ '^[a-f0-9]{64}$'), role text NOT NULL CHECK(role IN ('admin','member','guest')), invited_by uuid NOT NULL, expires_at timestamptz NOT NULL, accepted_by uuid, PRIMARY KEY(workspace_id,token_hash), FOREIGN KEY(workspace_id,invited_by) REFERENCES app.principals(workspace_id,id), FOREIGN KEY(workspace_id,accepted_by) REFERENCES app.principals(workspace_id,id)\n);\nALTER TABLE app.identity_invitations ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_invitations FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_invitations AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_invitations FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_invitations FROM PUBLIC, backbone_app, backbone_operator;\n\nGRANT SELECT,INSERT,UPDATE,DELETE ON app.identity_invitations TO backbone_gov;\n\n-- gov/identity_projects.sql\n\n-- Tenant identity state is crossing-only, including for the service role.\nCREATE TABLE app.identity_projects (\n  workspace_id uuid NOT NULL REFERENCES app.workspaces(id),\n  project_id uuid NOT NULL, owner_id uuid NOT NULL, PRIMARY KEY(workspace_id,project_id), FOREIGN KEY(workspace_id,owner_id) REFERENCES app.principals(workspace_id,id)\n);\nALTER TABLE app.identity_projects ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_projects FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_projects AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_projects FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_projects FROM PUBLIC, backbone_app, backbone_operator;\n\nGRANT SELECT,INSERT,UPDATE,DELETE ON app.identity_projects TO backbone_gov;\n\n-- gov/identity_project_people.sql\n\n-- Tenant identity state is crossing-only, including for the service role.\nCREATE TABLE app.identity_project_people (\n  workspace_id uuid NOT NULL REFERENCES app.workspaces(id),\n  project_id uuid NOT NULL, person_id uuid NOT NULL, access text NOT NULL CHECK(access IN ('viewer','editor')), PRIMARY KEY(workspace_id,project_id,person_id), FOREIGN KEY(workspace_id,project_id) REFERENCES app.identity_projects(workspace_id,project_id), FOREIGN KEY(workspace_id,person_id) REFERENCES app.principals(workspace_id,id)\n);\nALTER TABLE app.identity_project_people ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_project_people FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_project_people AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_project_people FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_project_people FROM PUBLIC, backbone_app, backbone_operator;\n\nGRANT SELECT,INSERT,UPDATE,DELETE ON app.identity_project_people TO backbone_gov;\n\n-- gov/identity_agents.sql\n\n-- Tenant identity state is crossing-only, including for the service role.\nCREATE TABLE app.identity_agents (\n  workspace_id uuid NOT NULL REFERENCES app.workspaces(id),\n  person_id uuid NOT NULL, carrier text NOT NULL, agent_id uuid NOT NULL, mandate_id uuid NOT NULL, PRIMARY KEY(workspace_id,person_id,carrier), FOREIGN KEY(workspace_id,person_id) REFERENCES app.principals(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES app.principals(workspace_id,id), FOREIGN KEY(workspace_id,mandate_id) REFERENCES app.mandates(workspace_id,id)\n);\nALTER TABLE app.identity_agents ENABLE ROW LEVEL SECURITY;\nALTER TABLE app.identity_agents FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_wall ON app.identity_agents AS RESTRICTIVE FOR ALL TO PUBLIC USING(workspace_id=sec.current_workspace()) WITH CHECK(workspace_id=sec.current_workspace());\nCREATE POLICY crossings ON app.identity_agents FOR ALL TO backbone_gov USING(true) WITH CHECK(true);\nREVOKE ALL ON app.identity_agents FROM PUBLIC, backbone_app, backbone_operator;\n\nGRANT SELECT,INSERT,UPDATE,DELETE ON app.identity_agents TO backbone_gov;\n\nSET ROLE backbone_gov;\n\n-- gov/identity_invite.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_invite(p_hash text, p_role text, p_expires timestamptz) RETURNS text\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid;\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||sec.current_workspace()::text,17));\n  PERFORM gov._lock_workspace(); me := gov._admin();\n  IF p_hash !~ '^[a-f0-9]{64}$' OR p_role NOT IN ('admin','member','guest') OR p_expires <= clock_timestamp() OR p_expires > clock_timestamp()+interval '7 days' THEN\n    RAISE EXCEPTION 'invalid: invitation role, token or expiry';\n  END IF;\n  INSERT INTO app.identity_invitations(workspace_id,token_hash,role,invited_by,expires_at)\n  VALUES(sec.current_workspace(),p_hash,p_role,me,p_expires);\n  PERFORM gov._append('identity.invited',p_hash,jsonb_build_object('role',p_role));\n  RETURN p_hash;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_invite(text,text,timestamptz) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_invite(text,text,timestamptz) TO backbone_app;\n\n-- gov/identity_accept.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_accept(p_hash text, p_issuer text, p_subject text, p_name text, p_session text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE inv record; person uuid := gen_random_uuid(); ws uuid := sec.current_workspace();\nBEGIN\n  IF sec.current_principal() IS NOT NULL OR sec.names_run() THEN RAISE EXCEPTION 'empty_session_only: accept without a principal'; END IF;\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17));\n  PERFORM gov._lock_workspace();\n  SELECT * INTO inv FROM app.identity_invitations WHERE workspace_id=ws AND token_hash=p_hash AND accepted_by IS NULL AND expires_at>clock_timestamp() FOR UPDATE;\n  IF NOT FOUND OR NOT sec.is_admin(inv.invited_by) THEN RAISE EXCEPTION 'invitation: unavailable invitation'; END IF;\n  IF nullif(p_issuer,'') IS NULL OR nullif(p_subject,'') IS NULL OR nullif(btrim(p_name),'') IS NULL OR p_session !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'invalid: identity binding'; END IF;\n  INSERT INTO app.principals(workspace_id,id,kind,role,name,user_id) VALUES(ws,person,'person',inv.role,p_name,person::text);\n  INSERT INTO app.identity_accounts(workspace_id,principal_id,issuer,subject) VALUES(ws,person,p_issuer,p_subject);\n  INSERT INTO app.identity_sessions(workspace_id,token_hash,principal_id,expires_at) VALUES(ws,p_session,person,clock_timestamp()+interval '12 hours');\n  UPDATE app.identity_invitations SET accepted_by=person WHERE workspace_id=ws AND token_hash=p_hash;\n  PERFORM gov._append('identity.accepted',person::text,jsonb_build_object('role',inv.role,'invited_by',inv.invited_by),person);\n  RETURN person;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_accept(text,text,text,text,text) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_accept(text,text,text,text,text) TO backbone_app;\n\n-- gov/identity_sign_in.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_sign_in(p_issuer text, p_subject text, p_session text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE person uuid; ws uuid := sec.current_workspace();\nBEGIN\n  IF sec.current_principal() IS NOT NULL OR sec.names_run() THEN RAISE EXCEPTION 'empty_session_only: sign in without a principal'; END IF;\n  PERFORM pg_advisory_xact_lock_shared(hashtextextended('identity:'||ws::text,17));\n  SELECT a.principal_id INTO person FROM app.identity_accounts a JOIN app.principals p ON p.workspace_id=a.workspace_id AND p.id=a.principal_id\n  WHERE a.workspace_id=ws AND a.issuer=p_issuer AND a.subject=p_subject AND p.status='active';\n  IF person IS NULL THEN RAISE EXCEPTION 'no_identity: account has no live membership'; END IF;\n  IF p_session !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'invalid: session token'; END IF;\n  INSERT INTO app.identity_sessions(workspace_id,token_hash,principal_id,expires_at) VALUES(ws,p_session,person,clock_timestamp()+interval '12 hours');\n  PERFORM gov._append('identity.signed_in',person::text,'{}',person);\n  RETURN person;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_sign_in(text,text,text) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_sign_in(text,text,text) TO backbone_app;\n\n-- gov/identity_session.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_session(p_hash text) RETURNS TABLE(principal uuid, name text, role text, expires_at timestamptz)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nBEGIN\n  RETURN QUERY SELECT p.id,p.name,p.role,s.expires_at FROM app.identity_sessions s JOIN app.principals p ON p.workspace_id=s.workspace_id AND p.id=s.principal_id\n  WHERE s.workspace_id=sec.current_workspace() AND s.token_hash=p_hash AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp() AND p.status='active';\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_session(text) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_session(text) TO backbone_app;\n\n-- gov/identity_people.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_people() RETURNS TABLE(id uuid, name text, role text, status text)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nBEGIN\n  PERFORM gov._admin();\n  RETURN QUERY SELECT p.id,p.name,p.role,p.status FROM app.principals p WHERE p.workspace_id=sec.current_workspace() AND p.kind='person' ORDER BY p.created_at,p.id;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_people() FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_people() TO backbone_app;\n\n-- gov/identity_remove.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_remove(p_person uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; target record; m record; ws uuid:=sec.current_workspace();\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17));\n  PERFORM gov._lock_workspace(); me:=gov._admin();\n  SELECT * INTO target FROM app.principals WHERE workspace_id=ws AND id=p_person AND kind='person' FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'not_found: no person'; END IF;\n  IF target.role='owner' AND (sec.role_of(me)<>'owner' OR NOT EXISTS(SELECT FROM app.principals WHERE workspace_id=ws AND kind='person' AND role='owner' AND status='active' AND id<>p_person)) THEN\n    RAISE EXCEPTION 'role: keep a live owner';\n  END IF;\n  IF target.status='removed' THEN RETURN p_person; END IF;\n  FOR m IN SELECT id FROM app.mandates WHERE workspace_id=ws AND revoked_at IS NULL AND (on_behalf_of_id=p_person OR issuer_id=p_person OR subject_id IN (SELECT id FROM app.principals WHERE workspace_id=ws AND owner_id=p_person)) ORDER BY created_at,id LOOP\n    PERFORM gov.revoke_mandate(m.id);\n  END LOOP;\n  UPDATE app.identity_sessions SET revoked_at=clock_timestamp() WHERE workspace_id=ws AND principal_id=p_person AND revoked_at IS NULL;\n  UPDATE app.identity_invitations SET expires_at=least(expires_at,clock_timestamp()) WHERE workspace_id=ws AND invited_by=p_person AND accepted_by IS NULL;\n  UPDATE app.principals SET status='removed' WHERE workspace_id=ws AND (id=p_person OR owner_id=p_person);\n  PERFORM gov._append('identity.removed',p_person::text,'{}',me);\n  RETURN p_person;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_remove(uuid) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_remove(uuid) TO backbone_app;\n\n-- gov/identity_change_role.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_change_role(p_person uuid, p_role text) RETURNS text\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; old text; m record; ws uuid:=sec.current_workspace();\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17));\n  PERFORM gov._lock_workspace(); me:=gov._admin(); old:=sec.role_of(p_person);\n  IF old='owner' AND p_role<>'owner' AND NOT EXISTS(SELECT FROM app.principals WHERE workspace_id=ws AND kind='person' AND role='owner' AND status='active' AND id<>p_person) THEN RAISE EXCEPTION 'role: keep a live owner'; END IF;\n  PERFORM gov.change_role(p_person,p_role);\n  IF p_role='guest' THEN\n    FOR m IN SELECT id FROM app.mandates WHERE workspace_id=ws AND on_behalf_of_id=p_person AND revoked_at IS NULL LOOP PERFORM gov.revoke_mandate(m.id); END LOOP;\n  END IF;\n  RETURN p_role;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_change_role(uuid,text) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_change_role(uuid,text) TO backbone_app;\n\n-- gov/identity_project_create.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_project_create(p_project uuid) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid;\nBEGIN\n  PERFORM pg_advisory_xact_lock_shared(hashtextextended('identity:'||sec.current_workspace()::text,17));\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF sec.role_of(me)='guest' THEN RAISE EXCEPTION 'role: guests do not create projects'; END IF;\n  INSERT INTO app.identity_projects(workspace_id,project_id,owner_id) VALUES(sec.current_workspace(),p_project,me);\n  PERFORM gov._append('identity.project_created',p_project::text,'{}');\n  RETURN p_project;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_project_create(uuid) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_project_create(uuid) TO backbone_app;\n\n-- gov/identity_project_access.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_project_access(p_project uuid) RETURNS text\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid:=sec.current_principal(); access text;\nBEGIN\n  IF me IS NULL OR sec.principal_kind(me)<>'person' THEN RETURN NULL; END IF;\n  SELECT CASE WHEN p.owner_id=me THEN 'owner' ELSE a.access END INTO access\n  FROM app.identity_projects p LEFT JOIN app.identity_project_people a ON a.workspace_id=p.workspace_id AND a.project_id=p.project_id AND a.person_id=me\n  WHERE p.workspace_id=sec.current_workspace() AND p.project_id=p_project;\n  IF sec.role_of(me)='guest' AND access IN ('owner','editor') THEN RETURN 'viewer'; END IF;\n  RETURN access;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_project_access(uuid) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_project_access(uuid) TO backbone_app;\n\n-- gov/identity_project_share.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_project_share(p_project uuid, p_person uuid, p_access text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE ws uuid:=sec.current_workspace(); me uuid;\nBEGIN\n  PERFORM pg_advisory_xact_lock(hashtextextended('identity:'||ws::text,17));\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF NOT EXISTS(SELECT FROM app.identity_projects WHERE workspace_id=ws AND project_id=p_project AND owner_id=me) THEN RAISE EXCEPTION 'denied: only the project owner shares it'; END IF;\n  IF p_access IS NOT NULL AND p_access NOT IN ('viewer','editor') THEN RAISE EXCEPTION 'invalid: project access'; END IF;\n  IF sec.role_of(p_person) IS NULL THEN RAISE EXCEPTION 'not_found: no active person'; END IF;\n  IF p_person=me THEN RAISE EXCEPTION 'invalid: the project owner keeps ownership'; END IF;\n  IF sec.role_of(p_person)='guest' AND p_access='editor' THEN RAISE EXCEPTION 'role: guests only view'; END IF;\n  IF p_access IS NULL THEN DELETE FROM app.identity_project_people WHERE workspace_id=ws AND project_id=p_project AND person_id=p_person;\n  ELSE INSERT INTO app.identity_project_people(workspace_id,project_id,person_id,access) VALUES(ws,p_project,p_person,p_access)\n    ON CONFLICT(workspace_id,project_id,person_id) DO UPDATE SET access=EXCLUDED.access;\n  END IF;\n  PERFORM gov._append('identity.project_shared',p_project::text,jsonb_build_object('person',p_person,'access',p_access));\n  RETURN p_project;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_project_share(uuid,uuid,text) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_project_share(uuid,uuid,text) TO backbone_app;\n\n-- gov/identity_runtime.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_runtime(p_piece uuid) RETURNS TABLE(agent uuid, mandate uuid)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nDECLARE me uuid; prior record; key text:=coalesce(p_piece::text,'direct'); a uuid; m uuid; ws uuid:=sec.current_workspace();\nBEGIN\n  PERFORM gov._lock_workspace(); me:=gov._person();\n  IF sec.role_of(me)='guest' THEN RAISE EXCEPTION 'role: guests run no automation'; END IF;\n  SELECT * INTO prior FROM app.identity_agents WHERE workspace_id=ws AND person_id=me AND carrier=key;\n  IF FOUND THEN\n    IF NOT EXISTS(SELECT FROM app.mandates WHERE workspace_id=ws AND id=prior.mandate_id AND revoked_at IS NULL AND expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'revoked: automation is closed'; END IF;\n    RETURN QUERY SELECT prior.agent_id,prior.mandate_id; RETURN;\n  END IF;\n  a:=gov.create_agent('Work for '||(SELECT name FROM app.principals WHERE workspace_id=ws AND id=me),'worker');\n  m:=gov.issue_mandate(a,NULL,'\"*\"','\"*\"','\"*\"','\"*\"',3::smallint,NULL,NULL,NULL,NULL,clock_timestamp()+interval '1 year',CASE WHEN p_piece IS NULL THEN 'direct' ELSE 'piece' END,'{}',p_piece);\n  INSERT INTO app.identity_agents(workspace_id,person_id,carrier,agent_id,mandate_id) VALUES(ws,me,key,a,m);\n  RETURN QUERY SELECT a,m;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_runtime(uuid) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_runtime(uuid) TO backbone_app;\n\n-- gov/identity_sign_out.sql\n\n-- Identity operations serialize admission and revocation before observing authority.\nCREATE FUNCTION gov.identity_sign_out(p_hash text) RETURNS boolean\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog\nAS $$\n#variable_conflict use_column\nBEGIN\n  UPDATE app.identity_sessions SET revoked_at=clock_timestamp() WHERE workspace_id=sec.current_workspace() AND token_hash=p_hash AND revoked_at IS NULL;\n  RETURN FOUND;\nEND\n$$;\nREVOKE ALL ON FUNCTION gov.identity_sign_out(text) FROM PUBLIC, backbone_operator;\nGRANT EXECUTE ON FUNCTION gov.identity_sign_out(text) TO backbone_app;\n\nRESET ROLE;\n"} as const);
